// Auto-generado desde github.com/hasaneyldrm/exercises-dataset (CC/atribución © Gym visual)
window.EXERCISES = [{"id":"0175","name":"cable kneeling crunch","grp":"core","eq":"polea","target":"abs","gif":"0175-WW95auq.gif","ins":"Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina. Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados. Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos"},{"id":"2801","name":"twisted leg raise (female)","grp":"core","eq":"peso corporal","target":"abs","gif":"2801-yT9tk17.gif","ins":"Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Flexiona las rodillas y levanta las piernas del suelo, llevándolas hacia el pecho. Mientras levantas las piernas, gira las caderas hacia un lado, llevando las rodillas hacia el hombro opuesto"},{"id":"1333","name":"exercise ball back extension with arms extended","grp":"core","eq":"fitball","target":"spine","gif":"1333-PERjVm8.gif","ins":"Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Extiende los brazos rectos hacia adelante, con las palmas hacia abajo. Activa el core y levanta lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta y el cuello alineado con la columna"},{"id":"0972","name":"band bicycle crunch","grp":"core","eq":"banda","target":"abs","gif":"0972-tZkGYZ9.gif","ins":"Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas. Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha. Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda"},{"id":"0491","name":"incline leg hip raise (leg straight)","grp":"core","eq":"peso corporal","target":"abs","gif":"0491-eVxAzgz.gif","ins":"Túmbate en un banco inclinado con la espalda apoyada plana en el banco y las piernas extendidas rectas frente a ti. Coloca las manos a los lados del banco para apoyarte. Activando el abdomen, levanta las piernas del banco, elevándolas tan alto como puedas mientras las mantienes rectas"},{"id":"0013","name":"assisted lying leg raise with throw down","grp":"core","eq":"asistido","target":"abs","gif":"0013-VX5YKR5.gif","ins":"Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el core y levanta las piernas del suelo, manteniéndolas rectas"},{"id":"0979","name":"band horizontal pallof press","grp":"core","eq":"banda","target":"abs","gif":"0979-9pa4H5m.gif","ins":"Sujeta la banda a un punto de anclaje resistente a la altura de la cintura. Ponte de pie perpendicular al punto de anclaje con los pies separados a la altura de los hombros. Agarra la agarradera de la banda con ambas manos y aléjate del punto de anclaje para generar tensión en la banda"},{"id":"0640","name":"one arm slam (with medicine ball)","grp":"core","eq":"balón medicinal","target":"abs","gif":"0640-jCrtE9b.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal con una mano frente a la cintura. Flexiona ligeramente las rodillas y activa el core. Eleva el balón medicinal por encima de la cabeza, extendiendo completamente el brazo"},{"id":"0096","name":"barbell side bent v. 2","grp":"core","eq":"barra","target":"abs","gif":"0096-i4JkUaL.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo. Mantén la espalda recta y el core activado durante todo el ejercicio. Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha"},{"id":"0242","name":"cable tuck reverse crunch","grp":"core","eq":"polea","target":"abs","gif":"0242-TXtXc84.gif","ins":"Sujeta un cable a una polea baja y túmbate boca arriba sobre una esterilla. Sujeta el cable con ambas manos y extiende los brazos rectos por encima del pecho. Flexiona las rodillas y levanta las piernas, llevando las rodillas hacia el pecho"},{"id":"1688","name":"lunge with twist","grp":"core","eq":"peso corporal","target":"abs","gif":"1688-K9VL0Jq.gif","ins":"Comienza de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Al hacer la zancada, gira el torso hacia la derecha, llevando el codo izquierdo hacia la rodilla derecha"},{"id":"0174","name":"cable judo flip","grp":"core","eq":"polea","target":"abs","gif":"0174-MvQPqVW.gif","ins":"Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo. Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo"},{"id":"1334","name":"exercise ball back extension with hands behind head","grp":"core","eq":"fitball","target":"spine","gif":"1334-o1HGDSq.gif","ins":"Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él con las caderas apoyadas en el balón. Coloca los pies contra una pared u otra superficie estable para apoyarte. Cruza los brazos detrás de la cabeza, con las manos tocando la parte de atrás de la cabeza"},{"id":"0870","name":"butt-ups","grp":"core","eq":"peso corporal","target":"abs","gif":"0870-qcNN2FN.gif","ins":"Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados, con las palmas hacia abajo. Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho"},{"id":"0969","name":"band alternating v-up","grp":"core","eq":"banda","target":"abs","gif":"0969-ztAa1RK.gif","ins":"Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda. Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies. Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra"},{"id":"0689","name":"seated leg raise","grp":"core","eq":"peso corporal","target":"abs","gif":"0689-Hgs6Nl1.gif","ins":"Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo. Coloca las manos a los lados del banco para apoyarte. Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo"},{"id":"0012","name":"assisted lying leg raise with lateral throw down","grp":"core","eq":"asistido","target":"abs","gif":"0012-UGhRD1A.gif","ins":"Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas"},{"id":"0488","name":"hyperextension (on bench)","grp":"core","eq":"peso corporal","target":"spine","gif":"0488-zkgRrbK.gif","ins":"Ajusta el banco de hiperextensiones para que las caderas queden apoyadas cómodamente en la almohadilla y los pies queden asegurados. Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza. Baja lentamente la parte superior del cuerpo hacia el suelo manteniendo la espalda recta"},{"id":"0756","name":"smith hip raise","grp":"core","eq":"multipower","target":"abs","gif":"0756-CqhoytW.gif","ins":"Colócate en la máquina Smith con la espalda contra la almohadilla y los pies separados a la altura de los hombros. Coloca las manos en la barra, un poco más separadas que el ancho de los hombros. Activa el core y los glúteos, luego empuja con los talones para levantar las caderas del suelo"},{"id":"0981","name":"band jack knife sit-up","grp":"core","eq":"banda","target":"abs","gif":"0981-KCBKjma.gif","ins":"Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda. Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial"},{"id":"0871","name":"tuck crunch","grp":"core","eq":"peso corporal","target":"abs","gif":"0871-BMMolZ3.gif","ins":"Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas"},{"id":"2963","name":"captains chair straight leg raise","grp":"core","eq":"peso corporal","target":"abs","gif":"2963-weoDEpH.gif","ins":"Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas. Mantén la parte superior del cuerpo estable y la espalda recta. Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas"},{"id":"3213","name":"side-to-side toe touch (male)","grp":"core","eq":"peso corporal","target":"abs","gif":"3213-WCAvOfC.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Dobla la cintura hacia la derecha, llevando la mano derecha hacia el pie derecho mientras mantienes la mano izquierda extendida hacia el lado. Vuelve a la posición inicial y luego dobla la cintura hacia la izquierda, llevando la mano izquierda hacia el pie izquierdo mientras mantienes la mano derecha extendida hacia el lado"},{"id":"0010","name":"assisted hanging knee raise with throw down","grp":"core","eq":"asistido","target":"abs","gif":"0010-8K0w2yA.gif","ins":"Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas. Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo"},{"id":"1343","name":"exercise ball prone leg raise","grp":"core","eq":"fitball","target":"spine","gif":"1343-lCKm4Rs.gif","ins":"Túmbate boca abajo sobre una esterilla con las piernas extendidas y los dedos de los pies apoyados sobre el balón de estabilidad. Coloca las manos en el suelo, separadas a la altura de los hombros, y activa el abdomen. Manteniendo las piernas rectas, levántalas lentamente del suelo, usando la zona lumbar y los glúteos para elevarlas tan alto como sea posible"},{"id":"0832","name":"weighted crunch","grp":"core","eq":"lastre","target":"abs","gif":"0832-s8nrDXF.gif","ins":"Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Sostén un disco de peso o una mancuerna sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que los omóplatos se separen del suelo"},{"id":"1015","name":"band vertical pallof press","grp":"core","eq":"banda","target":"abs","gif":"1015-G7PXMlT.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho. Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda. Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda"},{"id":"2466","name":"bridge - mountain climber (cross body)","grp":"core","eq":"peso corporal","target":"abs","gif":"2466-9c6T1YX.gif","ins":"Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo. Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho"},{"id":"1761","name":"hanging oblique knee raise","grp":"core","eq":"peso corporal","target":"abs","gif":"1761-BaE7O6U.gif","ins":"Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial"},{"id":"0472","name":"hanging leg raise","grp":"core","eq":"peso corporal","target":"abs","gif":"0472-I3tsCnC.gif","ins":"Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente"},{"id":"0573","name":"lever back extension","grp":"core","eq":"máquina","target":"spine","gif":"0573-rUXfn3R.gif","ins":"Ajusta la máquina según el tamaño de tu cuerpo y tu rango de movimiento. Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies asegurados. Coloca las manos en las asas o en las barras de agarre"},{"id":"0840","name":"weighted overhead crunch (on stability ball)","grp":"core","eq":"lastre","target":"abs","gif":"0840-xmM75XG.gif","ins":"Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén un disco de peso o una mancuerna con ambas manos y extiende los brazos por encima de la cabeza. Activa el abdomen y curva lentamente el torso hacia adelante, llevando el pecho hacia las rodillas"},{"id":"0777","name":"spell caster","grp":"core","eq":"mancuernas","target":"abs","gif":"0777-p9cCe2r.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta. Extiende el brazo con la mancuerna hacia el pie opuesto, rotando el torso mientras lo haces"},{"id":"0457","name":"flexion leg sit up (straight arm)","grp":"core","eq":"peso corporal","target":"abs","gif":"0457-KZn52RC.gif","ins":"Túmbate boca arriba con las piernas extendidas y los brazos rectos por encima de la cabeza. Activando el abdomen, levanta la parte superior del cuerpo del suelo mientras al mismo tiempo levantas las piernas hacia el pecho. Extiende las manos hacia los dedos de los pies mientras levantas la parte superior del cuerpo y las piernas"},{"id":"0469","name":"groin crunch","grp":"core","eq":"peso corporal","target":"abs","gif":"0469-mWppALS.gif","ins":"Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho"},{"id":"0112","name":"barbell standing twist","grp":"core","eq":"barra","target":"abs","gif":"0112-yQe5HpE.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo. Activa el core y mantén la espalda recta durante todo el ejercicio. Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo"},{"id":"0807","name":"suspended reverse crunch","grp":"core","eq":"peso corporal","target":"abs","gif":"0807-R1WYG5D.gif","ins":"Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y sube las rodillas hacia el pecho, curvando la pelvis hacia la caja torácica. Haz una pausa de un momento en la parte superior, luego baja lentamente las rodillas de nuevo a la posición inicial"},{"id":"0507","name":"jackknife sit-up","grp":"core","eq":"peso corporal","target":"abs","gif":"0507-mbkgB44.gif","ins":"Túmbate boca arriba con las piernas extendidas y los brazos por encima de la cabeza. Activa el core y levanta las piernas y la parte superior del cuerpo al mismo tiempo, llevando las manos hacia los dedos de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial"},{"id":"1314","name":"back extension on exercise ball","grp":"core","eq":"fitball","target":"spine","gif":"1314-qLpO4vV.gif","ins":"Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones"},{"id":"0634","name":"negative crunch","grp":"core","eq":"peso corporal","target":"abs","gif":"0634-szIn2UK.gif","ins":"Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados"},{"id":"3544","name":"bodyweight incline side plank","grp":"core","eq":"peso corporal","target":"abs","gif":"3544-5VXmnV5.gif","ins":"Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies"},{"id":"1335","name":"exercise ball back extension with knees off ground","grp":"core","eq":"fitball","target":"spine","gif":"1335-WME869U.gif","ins":"Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones"},{"id":"2429","name":"frog crunch","grp":"core","eq":"peso corporal","target":"abs","gif":"2429-FFRP97T.gif","ins":"Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados"},{"id":"0464","name":"front plank with twist","grp":"core","eq":"peso corporal","target":"abs","gif":"0464-CosupLu.gif","ins":"Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies. Activa el core y los glúteos para mantener una posición estable. Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo"},{"id":"3239","name":"kneeling plank tap shoulder (male)","grp":"core","eq":"peso corporal","target":"abs","gif":"3239-h1ezqSu.gif","ins":"Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros. Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha. Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto"},{"id":"0697","name":"self assisted inverse leg curl","grp":"piernas","eq":"peso corporal","target":"hamstrings","gif":"0697-GwYwElT.gif","ins":"Túmbate boca arriba sobre una esterilla o banco con las piernas extendidas. Coloca las manos a los lados o debajo de los glúteos para apoyarte. Dobla las rodillas y levanta los pies del suelo, llevando los muslos hacia el pecho"},{"id":"1585","name":"runners stretch","grp":"piernas","eq":"peso corporal","target":"hamstrings","gif":"1585-0mB6wHO.gif","ins":"Ponte de pie con los pies separados a la altura de la cadera. Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo. Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta"},{"id":"2315","name":"lever rotary calf","grp":"piernas","eq":"máquina","target":"calves","gif":"2315-MrgP9L6.gif","ins":"Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies. Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde. Sujeta las asas o los lados de la máquina para mayor estabilidad"},{"id":"1008","name":"band step-up","grp":"piernas","eq":"banda","target":"glutes","gif":"1008-d5bTEPV.gif","ins":"Coloca una banda alrededor de los muslos, justo por encima de las rodillas. Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas. Sube a la plataforma con el pie derecho, empujando con el talón"},{"id":"1370","name":"barbell floor calf raise","grp":"piernas","eq":"barra","target":"calves","gif":"1370-2IHEa2T.gif","ins":"Coloca una barra en el suelo frente a ti. Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando. Sujétate de un objeto estable para mantener el equilibrio si es necesario"},{"id":"0696","name":"self assisted inverse leg curl (on floor)","grp":"piernas","eq":"peso corporal","target":"hamstrings","gif":"0696-E4PwJqI.gif","ins":"Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Levanta las caderas del suelo, activando los glúteos y los isquiotibiales"},{"id":"0054","name":"barbell lunge","grp":"piernas","eq":"barra","target":"glutes","gif":"0054-t8iSghb.gif","ins":"Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda. Da un paso hacia delante con el pie derecho, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo"},{"id":"2567","name":"seated piriformis stretch","grp":"piernas","eq":"peso corporal","target":"glutes","gif":"2567-QY39eBr.gif","ins":"Siéntate en el suelo con las piernas extendidas frente a ti. Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda. Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha"},{"id":"1774","name":"side bridge hip abduction","grp":"piernas","eq":"peso corporal","target":"abductors","gif":"1774-WL4EmxJ.gif","ins":"Túmbate de lado con las piernas extendidas y una sobre la otra. Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies"},{"id":"3552","name":"quick feet v. 2","grp":"piernas","eq":"peso corporal","target":"quads","gif":"3552-mweqJin.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio. Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies"},{"id":"3643","name":"weighted cossack squats (male)","grp":"piernas","eq":"lastre","target":"glutes","gif":"3643-GWoKnIm.gif","ins":"Ponte de pie con los pies más separados que la anchura de los hombros y la punta de los pies apuntando ligeramente hacia afuera. Sostén un peso frente al pecho con ambas manos. Traslada tu peso hacia un lado y baja el cuerpo flexionando la rodilla del lado hacia el que te inclinaste, manteniendo la otra pierna recta"},{"id":"2812","name":"dumbbell step-up split squat","grp":"piernas","eq":"mancuernas","target":"quads","gif":"2812-QjE2DcA.gif","ins":"Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo"},{"id":"0851","name":"weighted sissy squat","grp":"piernas","eq":"lastre","target":"quads","gif":"0851-0lQnxMZ.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sostén un peso frente al pecho con ambas manos, o coloca una barra sobre la parte superior de la espalda. Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y las caderas"},{"id":"1009","name":"band stiff leg deadlift","grp":"piernas","eq":"banda","target":"glutes","gif":"1009-kuMiR2T.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los tobillos. Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo. Manteniendo la espalda recta y el core activado, flexiona las caderas y baja lentamente la parte superior del cuerpo hacia el suelo"},{"id":"1708","name":"assisted lying calves stretch","grp":"piernas","eq":"asistido","target":"calves","gif":"1708-GxDwDX0.gif","ins":"Túmbate sobre tu espalda con las piernas extendidas. Flexiona una rodilla y coloca el pie plano sobre el suelo. Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla"},{"id":"1548","name":"chair leg extended stretch","grp":"piernas","eq":"peso corporal","target":"quads","gif":"1548-xGgAGPm.gif","ins":"Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo. Extiende una pierna recta frente a ti, manteniendo el talón en el suelo. Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps"},{"id":"0668","name":"rear decline bridge","grp":"piernas","eq":"peso corporal","target":"glutes","gif":"0668-UpAlold.gif","ins":"Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas. Coloca los brazos a los lados del cuerpo con las palmas hacia abajo. Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros"},{"id":"0613","name":"lying (side) quads stretch","grp":"piernas","eq":"peso corporal","target":"quads","gif":"0613-BWnJR72.gif","ins":"Túmbate de lado con las piernas rectas. Flexiona la pierna de arriba y agarra tu tobillo o pie con la mano. Tira suavemente del tobillo o del pie hacia los glúteos hasta sentir un estiramiento en los cuádriceps"},{"id":"1462","name":"barbell full squat (side pov)","grp":"piernas","eq":"barra","target":"glutes","gif":"1462-iYzB0Cz.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo"},{"id":"3194","name":"frankenstein squat","grp":"piernas","eq":"barra","target":"glutes","gif":"3194-bdWcbaU.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén la barra frente al cuerpo con los brazos rectos. Manteniendo la espalda recta, baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente"},{"id":"0099","name":"barbell single leg split squat","grp":"piernas","eq":"barra","target":"quads","gif":"0099-gGNQmVt.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta"},{"id":"0108","name":"barbell standing leg calf raise","grp":"piernas","eq":"barra","target":"calves","gif":"0108-rGwhJ5o.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial"},{"id":"0097","name":"barbell side split squat v. 2","grp":"piernas","eq":"barra","target":"quads","gif":"0097-HUEqZ1y.gif","ins":"Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros. Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo"},{"id":"3562","name":"barbell glute bridge two legs on bench (male)","grp":"piernas","eq":"barra","target":"glutes","gif":"3562-qg2PGl6.gif","ins":"Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas. Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos. Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros"},{"id":"3281","name":"smith full squat","grp":"piernas","eq":"multipower","target":"glutes","gif":"3281-NNoHCEA.gif","ins":"Configura la máquina Smith con la barra a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios"},{"id":"0090","name":"barbell seated good morning","grp":"piernas","eq":"barra","target":"glutes","gif":"0090-d960PgE.gif","ins":"Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda. Mantén la espalda recta y el pecho elevado. Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo"},{"id":"0417","name":"dumbbell standing calf raise","grp":"piernas","eq":"mancuernas","target":"calves","gif":"0417-dPmaUaU.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial"},{"id":"1489","name":"sissy squat","grp":"piernas","eq":"peso corporal","target":"quads","gif":"1489-xdYPUtE.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido"},{"id":"1712","name":"assisted side lying adductor stretch","grp":"piernas","eq":"asistido","target":"adductors","gif":"1712-hC6oYY5.gif","ins":"Túmbate de lado con las piernas rectas y apiladas una sobre la otra. Flexiona ligeramente la pierna de abajo para mayor estabilidad. Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón"},{"id":"3543","name":"bodyweight drop jump squat","grp":"piernas","eq":"peso corporal","target":"glutes","gif":"3543-wfotm7S.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos"},{"id":"0730","name":"single leg platform slide","grp":"piernas","eq":"peso corporal","target":"hamstrings","gif":"0730-LNE3wfo.gif","ins":"Comienza de pie con un pie sobre una plataforma o tabla deslizante. Dobla ligeramente la rodilla y desliza el pie sobre la plataforma hacia atrás, extendiendo la pierna. Mantén el core activado y conserva una postura recta durante todo el movimiento"},{"id":"1253","name":"lever donkey calf raise","grp":"piernas","eq":"máquina","target":"calves","gif":"1253-C9LuR4A.gif","ins":"Ajusta la máquina de palanca a la altura adecuada para tu cuerpo. Colócate de frente a la máquina, con los dedos de los pies en la plataforma y los talones colgando fuera del borde. Coloca las manos en las asas o en las barras de soporte para mayor estabilidad"},{"id":"0431","name":"dumbbell step-up","grp":"piernas","eq":"mancuernas","target":"glutes","gif":"0431-aXtJhlg.gif","ins":"Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Empuja con el talón derecho y sube el cuerpo sobre el banco o escalón, enderezando la pierna derecha"},{"id":"0763","name":"smith reverse calf raises","grp":"piernas","eq":"multipower","target":"calves","gif":"0763-ywaNfuh.gif","ins":"Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante. Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando"},{"id":"0749","name":"smith bent knee good morning","grp":"piernas","eq":"multipower","target":"glutes","gif":"0749-1bQkKZK.gif","ins":"Comienza de pie con los pies separados a la altura de los hombros, con los dedos de los pies apuntando hacia delante. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta"},{"id":"3241","name":"exercise ball on the wall calf raise (tennis ball between ankles)","grp":"piernas","eq":"mancuernas","target":"calves","gif":"3241-FY3UdNT.gif","ins":"Ponte de pie frente a una pared con los pies separados a la altura de los hombros. Coloca un balón de ejercicio entre la pared y tu zona lumbar. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados"},{"id":"1386","name":"one leg donkey calf raise","grp":"piernas","eq":"peso corporal","target":"calves","gif":"1386-A2upspL.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Coloca las manos sobre una superficie estable para apoyarte, como una pared o una barra. Levanta una pierna del suelo, manteniendo la rodilla ligeramente flexionada"},{"id":"0053","name":"barbell jump squat","grp":"piernas","eq":"barra","target":"glutes","gif":"0053-1gFNTZV.gif","ins":"Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo"},{"id":"2287","name":"lever alternate leg press","grp":"piernas","eq":"máquina","target":"quads","gif":"2287-V07qpXy.gif","ins":"Ajusta el asiento y la plataforma para los pies de la máquina de palanca a la posición deseada. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma para los pies. Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad"},{"id":"0066","name":"barbell one arm side deadlift","grp":"piernas","eq":"barra","target":"glutes","gif":"0066-2DxtqHL.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado. Mantén la espalda recta y el core activado. Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado"},{"id":"3888","name":"dumbbell one arm snatch","grp":"piernas","eq":"mancuernas","target":"glutes","gif":"3888-6pTkI99.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo"},{"id":"0605","name":"lever standing calf raise","grp":"piernas","eq":"máquina","target":"calves","gif":"0605-ykUOVze.gif","ins":"Ajusta la máquina a tu altura y ponte de pie con los pies separados a la altura de los hombros. Coloca los hombros debajo de las almohadillas y sujétate de las asas para mayor estabilidad. Eleva los talones tan alto como puedas extendiendo los tobillos"},{"id":"3769","name":"curtsey squat","grp":"piernas","eq":"peso corporal","target":"glutes","gif":"3769-gUjqdei.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros. Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda. Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo"},{"id":"0769","name":"smith sprint lunge","grp":"piernas","eq":"multipower","target":"glutes","gif":"0769-HsjbB1z.gif","ins":"Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Da un paso atrás con el pie derecho y colócalo sobre la barra, apoyando la parte superior del pie en ella"},{"id":"1409","name":"barbell glute bridge","grp":"piernas","eq":"barra","target":"glutes","gif":"1409-qKBpF7I.gif","ins":"Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos. Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros"},{"id":"0589","name":"lever one arm bent over row","grp":"espalda","eq":"barra","target":"upper back","gif":"0589-Fhdtwf3.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con agarre prono. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la cabeza erguida. Deja que la barra cuelgue frente a ti con los brazos completamente extendidos"},{"id":"0499","name":"inverted row","grp":"espalda","eq":"peso corporal","target":"upper back","gif":"0499-bZGHsAZ.gif","ins":"Coloca una barra a la altura de la cintura o usa un entrenador de suspensión. Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros. Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros"},{"id":"3664","name":"dumbbell side plank with rear fly","grp":"espalda","eq":"mancuernas","target":"upper back","gif":"3664-X6ytgYZ.gif","ins":"Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca el antebrazo en el suelo, justo debajo del hombro, manteniendo el codo flexionado en un ángulo de 90 grados. Sujeta una mancuerna con la mano de arriba, con el brazo extendido recto hacia el suelo"},{"id":"0990","name":"band one arm twisting seated row","grp":"espalda","eq":"banda","target":"upper back","gif":"0990-DKBwJrL.gif","ins":"Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta. Sostén la banda con una mano y extiende el brazo completamente frente a ti. Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos"},{"id":"2464","name":"cable thibaudeau kayak row","grp":"espalda","eq":"polea","target":"lats","gif":"2464-ZgwWBoC.gif","ins":"Coloca un mango de cable en una polea baja y siéntate frente a la máquina con los pies planos en el suelo. Agarra el mango con la mano derecha y extiende completamente el brazo, manteniendo una ligera flexión en el codo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el abdomen activado"},{"id":"0761","name":"smith narrow row","grp":"espalda","eq":"multipower","target":"upper back","gif":"0761-JGKowMS.gif","ins":"Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo. Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros. Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas"},{"id":"1327","name":"close grip chin-up","grp":"espalda","eq":"peso corporal","target":"lats","gif":"1327-VnfUNW7.gif","ins":"Agarra la barra de dominadas con las palmas hacia ti y las manos separadas a la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo"},{"id":"1342","name":"exercise ball lying side lat stretch","grp":"espalda","eq":"fitball","target":"lats","gif":"1342-rTbyBYV.gif","ins":"Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el balón de estabilidad. Coloca el brazo de arriba sobre el balón para mantener la estabilidad. Extiende el brazo de arriba por encima de la cabeza y permite que tu torso gire ligeramente"},{"id":"2285","name":"lever pullover","grp":"espalda","eq":"máquina","target":"lats","gif":"2285-4U7iLb5.gif","ins":"Ajusta el asiento y las asas de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en la almohadilla y sujeta las asas con un agarre prono. Mantén los brazos ligeramente flexionados y el core activado"},{"id":"0571","name":"lever alternating narrow grip seated row","grp":"espalda","eq":"máquina","target":"upper back","gif":"0571-w2oRpuH.gif","ins":"Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta. Siéntate en la máquina con la espalda recta y los pies planos sobre la placa para los pies. Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra"},{"id":"0292","name":"dumbbell one arm bent-over row","grp":"espalda","eq":"mancuernas","target":"upper back","gif":"0292-C0MA9bC.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que la mancuerna cuelgue recta hacia el suelo, con el brazo completamente extendido"},{"id":"0172","name":"cable incline pushdown","grp":"espalda","eq":"polea","target":"lats","gif":"0172-1PK5Uo3.gif","ins":"Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros"},{"id":"1717","name":"cable squat row (with rope attachment)","grp":"espalda","eq":"polea","target":"lats","gif":"1717-f7fnAIB.gif","ins":"Sujeta una cuerda a una máquina de cable a la altura de la cintura. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado"},{"id":"1323","name":"cable rope seated row","grp":"espalda","eq":"polea","target":"upper back","gif":"1323-SJqRxOt.gif","ins":"Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos"},{"id":"0180","name":"cable low seated row","grp":"espalda","eq":"polea","target":"upper back","gif":"0180-hvV79Si.gif","ins":"Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos"},{"id":"1344","name":"ez bar reverse grip bent over row","grp":"espalda","eq":"barra Z","target":"upper back","gif":"1344-G8dXpNG.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo"},{"id":"1317","name":"barbell reverse grip incline bench row","grp":"espalda","eq":"barra","target":"upper back","gif":"1317-8d8qJQI.gif","ins":"Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco frente al respaldo con el pecho apoyado contra él. Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros"},{"id":"0574","name":"lever bent over row","grp":"espalda","eq":"barra","target":"upper back","gif":"0574-X3cqyXz.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado"},{"id":"0153","name":"cable cross-over lateral pulldown","grp":"espalda","eq":"polea","target":"lats","gif":"0153-OQ1otBN.gif","ins":"Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros. Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables"},{"id":"1326","name":"chin-up","grp":"espalda","eq":"peso corporal","target":"lats","gif":"1326-T2mxWqc.gif","ins":"Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Continúa subiendo hasta que la barbilla quede por encima de la barra"},{"id":"3166","name":"bodyweight standing row","grp":"espalda","eq":"peso corporal","target":"upper back","gif":"3166-wd4ds3s.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo. Mantén la espalda recta y el core activado"},{"id":"0049","name":"barbell incline row","grp":"espalda","eq":"barra","target":"upper back","gif":"0049-dmgMp3n.gif","ins":"Coloca un banco inclinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho apoyado en el respaldo y los pies planos sobre el suelo. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros"},{"id":"0983","name":"band kneeling one arm pulldown","grp":"espalda","eq":"banda","target":"lats","gif":"0983-pmnrOp0.gif","ins":"Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza. Arrodíllate y sostén la banda con una mano, con la palma hacia abajo. Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado"},{"id":"0498","name":"inverted row with straps","grp":"espalda","eq":"peso corporal","target":"upper back","gif":"0498-jdiExfW.gif","ins":"Coloca un entrenador de suspensión o correas a la altura del pecho. Ponte de pie frente al punto de anclaje y agarra las asas con agarre prono. Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en ángulo"},{"id":"1013","name":"band underhand pulldown","grp":"espalda","eq":"banda","target":"lats","gif":"1013-k6tUeqS.gif","ins":"Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros"},{"id":"0541","name":"kettlebell one arm row","grp":"espalda","eq":"kettlebell","target":"upper back","gif":"0541-g9AsZ8P.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos"},{"id":"1359","name":"smith bent over row","grp":"espalda","eq":"multipower","target":"upper back","gif":"1359-ZX9UZmj.gif","ins":"Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta"},{"id":"1341","name":"exercise ball lower back stretch (pyramid)","grp":"espalda","eq":"fitball","target":"lats","gif":"1341-yU7w7CA.gif","ins":"Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Camina lentamente hacia adelante con los pies, haciendo rodar el balón por tu espalda hasta que tu zona lumbar quede apoyada sobre el balón. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho"},{"id":"0184","name":"cable lying extension pullover (with rope attachment)","grp":"espalda","eq":"polea","target":"lats","gif":"0184-Q2Eu1Ax.gif","ins":"Sujeta una cuerda a una máquina de cable y coloca la polea en la posición más alta. Túmbate en un banco con la cabeza orientada hacia la máquina de cable. Sujeta la cuerda con ambas manos y extiende los brazos rectos por encima del pecho"},{"id":"2987","name":"weighted close grip chin-up on dip cage","grp":"espalda","eq":"lastre","target":"lats","gif":"2987-Gk1r408.gif","ins":"Ponte de pie frente a la jaula de fondos y agarra las barras paralelas con un agarre supino, con las manos separadas a la altura de los hombros. Cuélgate de las barras con los brazos completamente extendidos, los pies levantados del suelo y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba en dirección a las barras, manteniendo los codos cerca de los costados"},{"id":"1361","name":"smith reverse grip bent over row","grp":"espalda","eq":"multipower","target":"upper back","gif":"1361-aaxA3cm.gif","ins":"Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta"},{"id":"0652","name":"pull-up","grp":"espalda","eq":"peso corporal","target":"lats","gif":"0652-lBDjFxJ.gif","ins":"Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia la barra flexionando los codos y llevando el pecho hacia la barra"},{"id":"1772","name":"elbow lift - reverse push-up","grp":"espalda","eq":"peso corporal","target":"upper back","gif":"1772-wbUYILZ.gif","ins":"Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros. Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados. Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta"},{"id":"0974","name":"band close-grip pulldown","grp":"espalda","eq":"banda","target":"lats","gif":"0974-DptumMx.gif","ins":"Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente. Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros. Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas"},{"id":"3286","name":"weighted muscle up","grp":"espalda","eq":"lastre","target":"lats","gif":"3286-JsOV1SU.gif","ins":"Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti"},{"id":"0022","name":"barbell pullover to press","grp":"espalda","eq":"barra","target":"lats","gif":"0022-znLogoF.gif","ins":"Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales"},{"id":"1401","name":"muscle-up (on vertical bar)","grp":"espalda","eq":"peso corporal","target":"lats","gif":"1401-Af0EW2I.gif","ins":"Comienza colgándote de una barra vertical con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Al subir tu cuerpo, inclínate ligeramente hacia atrás y lleva los codos hacia los costados"},{"id":"1360","name":"smith one arm row","grp":"espalda","eq":"multipower","target":"upper back","gif":"1360-Q4DSJPC.gif","ins":"Ajusta la altura de la barra de la máquina Smith a la altura de la cintura. Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta"},{"id":"0581","name":"lever high row","grp":"espalda","eq":"máquina","target":"upper back","gif":"0581-nZZZy9m.gif","ins":"Ajusta la altura del asiento y la plataforma para los pies a una posición cómoda. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la plataforma para los pies. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros"},{"id":"3010","name":"ez bar lying bent arms pullover","grp":"espalda","eq":"barra Z","target":"lats","gif":"3010-nDK1HJ0.gif","ins":"Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sostén la barra EZ con agarre prono (palmas hacia afuera) y las manos separadas a la altura de los hombros. Extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos"},{"id":"0818","name":"twin handle parallel grip lat pulldown","grp":"espalda","eq":"polea","target":"lats","gif":"0818-rkg41Fb.gif","ins":"Ajusta la altura del asiento y colócate de frente a la máquina de cable. Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros. Siéntate y coloca los muslos debajo de las almohadillas para muslos, manteniendo los pies planos sobre el suelo"},{"id":"0674","name":"reverse grip pull-up","grp":"espalda","eq":"peso corporal","target":"lats","gif":"0674-YAk5dIw.gif","ins":"Agarra la barra de dominadas con un agarre supino, con las manos separadas a la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante"},{"id":"0627","name":"mixed grip chin-up","grp":"espalda","eq":"peso corporal","target":"lats","gif":"0627-T8UpLkb.gif","ins":"Agarra la barra de dominadas con un agarre supino (las palmas hacia ti) y las manos un poco más separadas que la anchura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante"},{"id":"0199","name":"cable pushdown (straight arm) v. 2","grp":"espalda","eq":"polea","target":"lats","gif":"0199-PskORrA.gif","ins":"Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo"},{"id":"3200","name":"lever bent-over row with v-bar","grp":"espalda","eq":"máquina","target":"upper back","gif":"3200-LuBEORI.gif","ins":"Ajusta la altura del asiento y colócate frente a la máquina. Sujeta la barra en V con un agarre prono, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Tira de la barra en V hacia el abdomen, juntando los omóplatos"},{"id":"0025","name":"barbell bench press","grp":"pecho","eq":"barra","target":"pectorals","gif":"0025-EIeI8Vf.gif","ins":"Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos"},{"id":"1304","name":"medicine ball chest push multiple response","grp":"pecho","eq":"balón medicinal","target":"pectorals","gif":"1304-7aolH9D.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho. Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho. Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho"},{"id":"0764","name":"smith reverse-grip press","grp":"pecho","eq":"multipower","target":"pectorals","gif":"0764-zK8Fu1W.gif","ins":"Ajusta la altura de la barra de la máquina Smith a la altura del pecho. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros"},{"id":"0493","name":"incline push-up","grp":"pecho","eq":"peso corporal","target":"pectorals","gif":"0493-B1EVP9F.gif","ins":"Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta"},{"id":"1258","name":"barbell wide reverse grip bench press","grp":"pecho","eq":"barra","target":"pectorals","gif":"1258-945zpRg.gif","ins":"Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos"},{"id":"1274","name":"deep push up","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1274-vptOQ4N.gif","ins":"Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Empuja con las palmas para extender los brazos y regresar a la posición inicial"},{"id":"0658","name":"push-up (wall) v. 2","grp":"pecho","eq":"peso corporal","target":"pectorals","gif":"0658-NCmbLCw.gif","ins":"Ponte de pie frente a una pared, a una distancia aproximada de un brazo. Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros. Retrocede con los pies, manteniéndolos separados a la altura de las caderas"},{"id":"1270","name":"cable upper chest crossovers","grp":"pecho","eq":"polea","target":"pectorals","gif":"1270-j7XMAyn.gif","ins":"Coloca los mangos en los cables a la altura del pecho. Ponte de pie en el centro de la máquina de cable con un pie ligeramente delante del otro. Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados"},{"id":"1291","name":"dumbbell one arm pullover on exercise ball","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1291-bQHPBU3.gif","ins":"Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto"},{"id":"1277","name":"dumbbell fly on exercise ball","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1277-Lt3iWnf.gif","ins":"Siéntate sobre un balón de estabilidad y sostén una mancuerna en cada mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Extiende los brazos rectos por encima del pecho, con las palmas enfrentadas entre sí"},{"id":"1261","name":"cable decline press","grp":"pecho","eq":"polea","target":"pectorals","gif":"1261-2Pya1cP.gif","ins":"Ajusta la máquina de cable a una posición declinada. Siéntate en el banco declinado frente a la máquina de cable. Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho"},{"id":"0433","name":"dumbbell straight arm pullover","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"0433-i8BdLTK.gif","ins":"Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza con un movimiento en forma de arco"},{"id":"3313","name":"weighted straight bar dip","grp":"pecho","eq":"lastre","target":"pectorals","gif":"3313-Ff18ItA.gif","ins":"Colócate entre las barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos"},{"id":"1295","name":"dumbbell pullover on exercise ball","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1295-FSD6PGL.gif","ins":"Siéntate sobre un balón de estabilidad y sujeta una mancuerna con ambas manos por encima del pecho, con los brazos extendidos. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial"},{"id":"0666","name":"raise single arm push-up","grp":"pecho","eq":"peso corporal","target":"pectorals","gif":"0666-13TpY4H.gif","ins":"Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Extiende un brazo hacia el lado, paralelo al suelo. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado"},{"id":"3234","name":"hyght dumbbell fly","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"3234-P9ZRyLT.gif","ins":"Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Manteniendo una ligera flexión en los codos, baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho"},{"id":"1294","name":"dumbbell pullover hip extension on exercise ball","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1294-lI7easp.gif","ins":"Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos"},{"id":"3785","name":"incline push-up (on box)","grp":"pecho","eq":"peso corporal","target":"pectorals","gif":"3785-F7vjXqT.gif","ins":"Coloca las manos en el borde de una caja o una superficie elevada, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la caja doblando los codos, manteniendo el cuerpo en línea recta"},{"id":"1624","name":"dumbbell reverse bench press","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1624-UIbGx6H.gif","ins":"Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies. Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos"},{"id":"0045","name":"barbell guillotine bench press","grp":"pecho","eq":"barra","target":"pectorals","gif":"0045-GXoaSgn.gif","ins":"Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera"},{"id":"1299","name":"lever incline chest press","grp":"pecho","eq":"máquina","target":"pectorals","gif":"1299-jHAnWmT.gif","ins":"Ajusta el asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros"},{"id":"1310","name":"weighted drop push up","grp":"pecho","eq":"lastre","target":"pectorals","gif":"1310-PSlvNMs.gif","ins":"Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Cuando el pecho esté justo por encima del suelo, empújate hacia arriba de forma explosiva, levantando las manos del suelo"},{"id":"1716","name":"assisted seated pectoralis major stretch with stability ball","grp":"pecho","eq":"asistido","target":"pectorals","gif":"1716-RoV1Rfa.gif","ins":"Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti. Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales"},{"id":"3124","name":"resistance band seated chest press","grp":"pecho","eq":"banda","target":"pectorals","gif":"3124-4x5Okof.gif","ins":"Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén las asas de la banda elástica en cada mano, con las palmas hacia abajo y los codos flexionados en un ángulo de 90 grados. Extiende los brazos hacia adelante, alejando la banda elástica de tu pecho"},{"id":"1255","name":"barbell decline pullover","grp":"pecho","eq":"barra","target":"pectorals","gif":"1255-9sgNE2O.gif","ins":"Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos. Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros. Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos"},{"id":"1284","name":"dumbbell lying pullover on exercise ball","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1284-iK59oEA.gif","ins":"Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el balón. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos"},{"id":"1479","name":"lever incline chest press v. 2","grp":"pecho","eq":"máquina","target":"pectorals","gif":"1479-o17Jfkt.gif","ins":"Ajusta la altura del asiento y el ángulo del respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros"},{"id":"3545","name":"dumbbell incline alternate press","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"3545-TVdivgY.gif","ins":"Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Una vez a la altura de los hombros, gira las muñecas de modo que las palmas de las manos queden mirando hacia adelante"},{"id":"3758","name":"lever standing chest press","grp":"pecho","eq":"máquina","target":"pectorals","gif":"3758-WbNq5Xu.gif","ins":"Ajusta la altura del asiento y colócate en la máquina con los pies planos en el suelo. Agarra las asas con un agarre prono y coloca las manos a la altura del pecho. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, manteniendo los codos ligeramente flexionados"},{"id":"0158","name":"cable decline fly","grp":"pecho","eq":"polea","target":"pectorals","gif":"0158-7saC5zz.gif","ins":"Ajusta la máquina de cable a una posición declinada. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti"},{"id":"3216","name":"chest tap push-up (male)","grp":"pecho","eq":"peso corporal","target":"pectorals","gif":"3216-7E06s6d.gif","ins":"Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras te bajas, toca tu pecho con la mano derecha"},{"id":"0342","name":"dumbbell lying one arm press v. 2","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"0342-K3dIO25.gif","ins":"Túmbate boca arriba en un banco con la espalda apoyada y los pies planos sobre el suelo. Sostén una mancuerna en una mano con la palma hacia los pies. Extiende el brazo recto hacia el techo, manteniendo el codo ligeramente flexionado"},{"id":"1305","name":"medicine ball chest push single response","grp":"pecho","eq":"balón medicinal","target":"pectorals","gif":"1305-jeHtrlO.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho. Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho. Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho"},{"id":"0151","name":"cable bench press","grp":"pecho","eq":"polea","target":"pectorals","gif":"0151-7xI5MXA.gif","ins":"Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables"},{"id":"1285","name":"dumbbell one arm bench fly","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1285-o5Jsk92.gif","ins":"Siéntate en un banco plano con una mancuerna en una mano, apoyándola sobre el muslo. Recuéstate en el banco, manteniendo la mancuerna presionada contra el muslo. Usando la mano libre, ayuda a levantar la mancuerna hasta la posición inicial"},{"id":"1264","name":"cable one arm incline fly on exercise ball","grp":"pecho","eq":"polea","target":"pectorals","gif":"1264-P14Dz9D.gif","ins":"Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado. Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro. Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro"},{"id":"1254","name":"band bench press","grp":"pecho","eq":"banda","target":"pectorals","gif":"1254-khlHMqs.gif","ins":"Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros. Extiende los brazos por completo, empujando las bandas alejándolas del pecho"},{"id":"1287","name":"dumbbell one arm decline chest press","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1287-REGM1dE.gif","ins":"Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho. Coloca los pies planos sobre el suelo y mantén la espalda presionada contra el banco. Extiende el brazo y empuja la mancuerna hacia el techo, extendiendo completamente el codo"},{"id":"1309","name":"smith wide grip decline bench press","grp":"pecho","eq":"multipower","target":"pectorals","gif":"1309-wi2H9QX.gif","ins":"Ajusta el banco declinado al ángulo deseado. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros"},{"id":"1282","name":"dumbbell incline one arm press on exercise ball","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1282-Bg5JKSH.gif","ins":"Siéntate sobre un balón de estabilidad con una mancuerna en una mano, con los pies apoyados en el suelo. Camina lentamente con los pies hacia adelante, haciendo rodar el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna a la altura del hombro con la palma hacia adelante"},{"id":"0185","name":"cable lying fly","grp":"pecho","eq":"polea","target":"pectorals","gif":"0185-lJJ7Yq8.gif","ins":"Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo. Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho. Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho"},{"id":"1167","name":"dynamic chest stretch (male)","grp":"pecho","eq":"peso corporal","target":"pectorals","gif":"1167-3uj0Ozg.gif","ins":"Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos hacia los lados, paralelos al suelo. Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo"},{"id":"0171","name":"cable incline fly","grp":"pecho","eq":"polea","target":"pectorals","gif":"0171-tBWXbIT.gif","ins":"Ajusta la máquina de cable a una posición baja y sujeta las agarraderas. Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti"},{"id":"0758","name":"smith incline reverse-grip press","grp":"pecho","eq":"multipower","target":"pectorals","gif":"0758-78VqWQK.gif","ins":"Ajusta el asiento de la máquina Smith a un ángulo de inclinación cómodo. Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo. Sujeta la barra con un agarre prono un poco más ancho que el ancho de los hombros"},{"id":"1278","name":"dumbbell incline fly on exercise ball","grp":"pecho","eq":"mancuernas","target":"pectorals","gif":"1278-HYe1ZqR.gif","ins":"Coloca un banco inclinado a un ángulo de 45 grados. Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el banco inclinado. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho"},{"id":"1751","name":"barbell pin presses","grp":"triceps","eq":"barra","target":"triceps","gif":"1751-bndCa3Q.gif","ins":"Coloca una barra en un rack de potencia a la altura del pecho. Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros"},{"id":"0398","name":"dumbbell seated one arm kickback","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"0398-VQ3sNCn.gif","ins":"Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano. Inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo"},{"id":"0639","name":"one arm dip","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"0639-FAoIFMw.gif","ins":"Ponte de pie de espaldas a un banco o silla, con los pies separados a la altura de los hombros. Coloca una mano en el banco o silla detrás de ti, con los dedos apuntando hacia tu cuerpo. Extiende las piernas hacia adelante, manteniendo los talones en el suelo"},{"id":"0660","name":"push-up close-grip off dumbbell","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"0660-KZXAtKQ.gif","ins":"Comienza en posición de flexión con las manos juntas, directamente debajo de los hombros. Sostén una mancuerna en cada mano, apoyándolas en el suelo. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados"},{"id":"0055","name":"barbell lying close-grip press","grp":"triceps","eq":"barra","target":"triceps","gif":"0055-EcaV7aL.gif","ins":"Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas mirando hacia los pies. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos"},{"id":"1619","name":"dumbbell incline one arm hammer press","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"1619-LL1UiTX.gif","ins":"Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo. Recuéstate en el banco y usa el muslo para ayudar a levantar la mancuerna hasta la altura de los hombros. Gira la muñeca de modo que la palma quede mirando hacia adentro, hacia el cuerpo"},{"id":"0337","name":"dumbbell lying extension (across face)","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"0337-L2V5Nan.gif","ins":"Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho, con las palmas enfrentadas entre sí. Manteniendo los brazos superiores quietos, baja lentamente la mancuerna describiendo un arco detrás de la cabeza hasta que los antebrazos queden paralelos al suelo"},{"id":"1748","name":"ez bar lying close grip triceps extension behind head","grp":"triceps","eq":"barra Z","target":"triceps","gif":"1748-6CKUx7o.gif","ins":"Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sostén la barra EZ con agarre cerrado, palmas hacia arriba, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos"},{"id":"0018","name":"assisted standing triceps extension (with towel)","grp":"triceps","eq":"asistido","target":"triceps","gif":"0018-7HcfMBP.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza. Mantén los codos cerca de las orejas y la parte superior de los brazos quieta. Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior"},{"id":"1741","name":"dumbbell standing bent over two arm triceps extension","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"1741-3T12T87.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo"},{"id":"1701","name":"medicine ball close grip push up","grp":"triceps","eq":"balón medicinal","target":"triceps","gif":"1701-8K7m2SS.gif","ins":"Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Empuja de vuelta hasta la posición inicial, extendiendo completamente los brazos"},{"id":"1727","name":"cable standing reverse grip one arm overhead tricep extension","grp":"triceps","eq":"polea","target":"triceps","gif":"1727-i11JWU7.gif","ins":"Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre supino y extiende el brazo por encima de la cabeza, manteniendo el codo cerca de la cabeza. Mantén el brazo superior quieto y baja lentamente el mango del cable detrás de la cabeza flexionando el codo"},{"id":"1744","name":"exercise ball dip","grp":"triceps","eq":"fitball","target":"triceps","gif":"1744-kprile3.gif","ins":"Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos sobre el balón junto a las caderas, con los dedos apuntando hacia adelante. Activa el tríceps y empuja con las manos para levantar el cuerpo del balón, enderezando los brazos"},{"id":"0815","name":"triceps dips floor","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"0815-7aVz15j.gif","ins":"Siéntate en el borde de una silla o banco con las manos junto a las caderas, los dedos apuntando hacia adelante. Desliza los glúteos fuera del frente de la silla con las piernas extendidas frente a ti. Estira los brazos, manteniendo una ligera flexión en los codos para conservar la tensión en los tríceps y aliviarla en las articulaciones del codo"},{"id":"0816","name":"triceps press","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"0816-fSrPP6B.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos rectos frente a ti, paralelos al suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la parte superior de los brazos cerca de los costados"},{"id":"0677","name":"ring dips","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"0677-ezTvXcr.gif","ins":"Comienza colgándote de las anillas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos"},{"id":"0204","name":"cable rear drive","grp":"triceps","eq":"polea","target":"triceps","gif":"0204-c3QQLPi.gif","ins":"Sujeta una agarradera a una máquina de cable con polea baja y ponte de pie de espaldas a la máquina. Sujeta la agarradera con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo los codos inmóviles, jala la agarradera de vuelta hacia el cuerpo, apretando los tríceps al final del movimiento"},{"id":"1738","name":"dumbbell seated reverse grip one arm overhead tricep extension","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"1738-5fKX7wi.gif","ins":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con agarre supino y extiende el brazo recto por encima de la cabeza. Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto"},{"id":"0152","name":"cable concentration extension (on knee)","grp":"triceps","eq":"polea","target":"triceps","gif":"0152-Db7eEgw.gif","ins":"Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo. Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha. Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla"},{"id":"0354","name":"dumbbell one arm kickback","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"0354-bQy2Eni.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados"},{"id":"0200","name":"cable pushdown (with rope attachment)","grp":"triceps","eq":"polea","target":"triceps","gif":"0200-dU605di.gif","ins":"Sujeta un accesorio de cuerda a una polea alta en una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra"},{"id":"1746","name":"exercise ball supine triceps extension","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"1746-Gm2Uv1z.gif","ins":"Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia el techo. Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas"},{"id":"0814","name":"triceps dip","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"0814-X6C6i5Y.gif","ins":"Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco"},{"id":"0149","name":"cable alternate triceps extension","grp":"triceps","eq":"polea","target":"triceps","gif":"0149-Gchi5Tr.gif","ins":"Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados. Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo"},{"id":"0860","name":"cable kickback","grp":"triceps","eq":"polea","target":"triceps","gif":"0860-HEJ6DIX.gif","ins":"Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta"},{"id":"1754","name":"weighted three bench dips","grp":"triceps","eq":"lastre","target":"triceps","gif":"1754-gtO1ErP.gif","ins":"Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Camina con los pies hacia adelante, deslizando los glúteos fuera del banco y sosteniendo tu peso con los brazos. Baja el cuerpo flexionando los codos, manteniendo la espalda cerca del banco"},{"id":"0423","name":"dumbbell standing one arm extension","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"0423-BCUR88E.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo. Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo"},{"id":"0057","name":"barbell lying extension","grp":"triceps","eq":"barra","target":"triceps","gif":"0057-EMpUwRI.gif","ins":"Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos"},{"id":"0186","name":"cable lying triceps extension v. 2","grp":"triceps","eq":"polea","target":"triceps","gif":"0186-uxJcFUU.gif","ins":"Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con la cabeza orientada hacia la máquina de cable. Sujeta la agarradera de cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos por encima del pecho"},{"id":"1734","name":"dumbbell kickbacks on exercise ball","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"1734-cAvTaSg.gif","ins":"Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento"},{"id":"0201","name":"cable pushdown","grp":"triceps","eq":"polea","target":"triceps","gif":"0201-3ZflifB.gif","ins":"Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros"},{"id":"0296","name":"dumbbell close-grip press","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"0296-RxayqAZ.gif","ins":"Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos. Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros. Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti"},{"id":"3291","name":"stalder press","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"3291-zd4P4B2.gif","ins":"Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos por encima de la cabeza. Flexiona ligeramente las rodillas y activa el core. Baja el cuerpo a una posición de sentadilla mientras mantienes los brazos extendidos por encima de la cabeza"},{"id":"2398","name":"close-grip push-up (on knees)","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"2398-v3vLFW0.gif","ins":"Comienza apoyándote sobre las manos y las rodillas, con las manos separadas a la altura de los hombros y las rodillas separadas a la altura de las caderas. Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Haz una pausa breve cuando tu pecho esté justo por encima del suelo"},{"id":"0259","name":"close-grip push-up","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"0259-x6KpKpq.gif","ins":"Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial"},{"id":"1749","name":"ez bar standing french press","grp":"triceps","eq":"barra Z","target":"triceps","gif":"1749-1cTf2Ux.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos"},{"id":"0812","name":"triceps dip (bench leg)","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"0812-VuoerH0.gif","ins":"Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Camina con los pies hacia adelante, deslizando los glúteos fuera del banco, y estira los brazos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco"},{"id":"0373","name":"dumbbell pronate-grip triceps extension","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"0373-bpJL2Qs.gif","ins":"Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo. Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza. Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos"},{"id":"0436","name":"dumbbell tate press","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"0436-s5PdDyY.gif","ins":"Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí. Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros"},{"id":"1729","name":"dumbbell lying alternate extension","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"1729-NfP83rA.gif","ins":"Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Baja una mancuerna hacia la cabeza, flexionando el codo, mientras mantienes el otro brazo extendido"},{"id":"1621","name":"dumbbell one arm hammer press on exercise ball","grp":"triceps","eq":"mancuernas","target":"triceps","gif":"1621-VYmYxK5.gif","ins":"Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados. Coloca la otra mano en la cadera para mantener el equilibrio"},{"id":"1747","name":"ez bar french press on exercise ball","grp":"triceps","eq":"barra Z","target":"triceps","gif":"1747-CFN9P8G.gif","ins":"Siéntate sobre un balón de ejercicio y sostén una barra EZ con agarre prono. Extiende los brazos rectos hacia arriba, manteniendo los codos cerca de la cabeza. Baja lentamente la barra detrás de la cabeza doblando los codos"},{"id":"0643","name":"overhead triceps stretch","grp":"triceps","eq":"peso corporal","target":"triceps","gif":"0643-Z5YStHW.gif","ins":"Ponte de pie o siéntate erguido con los pies separados a la altura de los hombros. Extiende un brazo por encima de la cabeza, flexionando el codo de modo que la mano llegue hacia la escápula opuesta. Con la otra mano, tira suavemente del codo del brazo extendido hacia el lado opuesto de la cabeza, sintiendo un estiramiento en el tríceps"},{"id":"1750","name":"medicine ball supine chest throw","grp":"triceps","eq":"balón medicinal","target":"triceps","gif":"1750-Al3tP0D.gif","ins":"Túmbate boca arriba en un banco con las rodillas flexionadas y los pies planos en el suelo. Sostén el balón medicinal con ambas manos, extendiendo los brazos rectos por encima del pecho. Baja el balón medicinal hacia el pecho, manteniendo los codos cerca del cuerpo"},{"id":"0019","name":"assisted triceps dip (kneeling)","grp":"triceps","eq":"máquina","target":"triceps","gif":"0019-J60bN17.gif","ins":"Ajusta la máquina al peso y la altura deseados. Arrodíllate sobre la almohadilla frente a la máquina, con las manos sujetando las agarraderas. Baja el cuerpo flexionando los codos, manteniendo la espalda recta y cerca de la máquina"},{"id":"1680","name":"dumbbell standing one arm curl over incline bench","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1680-EmlJR2y.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Coloca la otra mano sobre un banco inclinado para apoyarte. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps"},{"id":"1679","name":"dumbbell seated one arm bicep curl on exercise ball with leg raised","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1679-84sESNy.gif","ins":"Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido. Coloca la otra mano en la cadera para mantener el equilibrio"},{"id":"2414","name":"barbell standing concentration curl","grp":"biceps","eq":"barra","target":"biceps","gif":"2414-vsMcDi9.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba. Apoya la otra mano sobre el muslo para mayor estabilidad. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro"},{"id":"1413","name":"cable reverse one arm curl","grp":"biceps","eq":"polea","target":"biceps","gif":"1413-gVlnLIJ.gif","ins":"Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino, con la palma hacia abajo. Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro"},{"id":"0224","name":"cable standing back wrist curl","grp":"biceps","eq":"polea","target":"forearms","gif":"0224-VhX2JdE.gif","ins":"Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre prono, con las palmas hacia abajo. Mantén los brazos rectos y los codos cerca de los costados"},{"id":"0298","name":"dumbbell cross body hammer curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0298-Qyk5J3p.gif","ins":"Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona los brazos contrayendo los bíceps, llevando las mancuernas a través del cuerpo hacia el hombro opuesto"},{"id":"1616","name":"lever reverse grip preacher curl","grp":"biceps","eq":"máquina","target":"biceps","gif":"1616-kj3hy6W.gif","ins":"Ajusta la altura del asiento y colócate en la máquina de palanca. Sujeta las asas con un agarre supino, con las palmas hacia arriba. Apoya los brazos superiores sobre la almohadilla de predicador, asegurándote de que los codos queden completamente extendidos"},{"id":"0451","name":"ez barbell reverse grip curl","grp":"biceps","eq":"barra Z","target":"biceps","gif":"0451-Y5X65IB.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino. Mantén los codos cerca del torso y los brazos superiores inmóviles durante todo el ejercicio. Sube la barra contrayendo los bíceps, mientras exhalas"},{"id":"0140","name":"biceps pull-up","grp":"biceps","eq":"peso corporal","target":"biceps","gif":"0140-guT8YnS.gif","ins":"Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra. Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial"},{"id":"1628","name":"ez barbell spider curl","grp":"biceps","eq":"barra Z","target":"biceps","gif":"1628-2kattbR.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros"},{"id":"0247","name":"cable wrist curl","grp":"biceps","eq":"polea","target":"forearms","gif":"0247-LrV4s90.gif","ins":"Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros"},{"id":"0297","name":"dumbbell concentration curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0297-gvsWLQw.gif","ins":"Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la parte interna del muslo. Extiende completamente el brazo y sujeta la mancuerna con un agarre supino. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro mientras contraes el bíceps"},{"id":"0428","name":"dumbbell standing preacher curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0428-hq2hyDH.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Apoya la parte posterior de la parte superior de los brazos contra el banco scott o un banco inclinado, con los codos ligeramente flexionados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps"},{"id":"1661","name":"dumbbell lying supine biceps curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1661-XVzF3iZ.gif","ins":"Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps"},{"id":"0165","name":"cable hammer curl (with rope)","grp":"biceps","eq":"polea","target":"biceps","gif":"0165-HPlPoQA.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps"},{"id":"1645","name":"cable two arm curl on incline bench","grp":"biceps","eq":"polea","target":"biceps","gif":"1645-H9y3Dkr.gif","ins":"Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra los mangos del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona los mangos hacia los hombros mientras contraes los bíceps"},{"id":"1656","name":"dumbbell biceps curl v sit on bosu ball","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1656-H1XAdpk.gif","ins":"Siéntate en un bosu con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos hacia abajo a los lados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps"},{"id":"1653","name":"dumbbell bicep curl with stork stance","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1653-uSkDMYl.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Extiende una pierna hacia atrás, equilibrándote sobre los dedos de ese pie. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps"},{"id":"0976","name":"band concentration curl","grp":"biceps","eq":"banda","target":"biceps","gif":"0976-kmVVAfu.gif","ins":"Siéntate en un banco o silla con las piernas separadas y los pies apoyados en el suelo. Sostén un extremo de la banda en la mano y pisa el otro extremo con el pie del mismo lado. Inclínate ligeramente hacia adelante y apoya el codo en la parte interna del muslo, justo encima de la rodilla"},{"id":"0139","name":"biceps narrow pull-ups","grp":"biceps","eq":"peso corporal","target":"biceps","gif":"0139-50BETrz.gif","ins":"Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial"},{"id":"1770","name":"biceps leg concentration curl","grp":"biceps","eq":"peso corporal","target":"biceps","gif":"1770-sJFIDIp.gif","ins":"Siéntate en un banco con las piernas separadas y los pies planos en el suelo. Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla. Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto"},{"id":"0366","name":"dumbbell over bench one arm neutral wrist curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0366-IvV6C9M.gif","ins":"Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial"},{"id":"0349","name":"dumbbell lying supination","grp":"biceps","eq":"mancuernas","target":"forearms","gif":"0349-M2Pm3zj.gif","ins":"Túmbate boca arriba en un banco con los pies planos sobre el suelo. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, flexiona las mancuernas hacia los hombros contrayendo los antebrazos"},{"id":"0418","name":"dumbbell standing concentration curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0418-7inpWch.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano, con el brazo completamente extendido y la palma hacia adentro. Apoya la otra mano sobre el muslo para mayor estabilidad. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps"},{"id":"0636","name":"olympic barbell hammer curl","grp":"biceps","eq":"barra olímpica","target":"biceps","gif":"0636-o1ntciW.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra olímpica con un agarre prono. Deja que la barra cuelgue a la altura de los brazos frente a tus muslos, con las palmas hacia tu cuerpo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps"},{"id":"1642","name":"cable seated one arm concentration curl","grp":"biceps","eq":"polea","target":"biceps","gif":"1642-rZ80Gbp.gif","ins":"Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y coloca el codo en la parte interna del muslo, justo arriba de la rodilla. Mantén la parte superior del brazo inmóvil y curva la agarradera del cable hacia el hombro mientras exhalas"},{"id":"1659","name":"dumbbell hammer curl on exercise ball","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1659-fY68AyX.gif","ins":"Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps"},{"id":"0320","name":"dumbbell incline hammer curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0320-ByX0WxV.gif","ins":"Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia el torso y los brazos completamente extendidos. Mantén la espalda contra el banco y los pies apoyados en el suelo. Manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps"},{"id":"0391","name":"dumbbell seated curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0391-TiaZTxx.gif","ins":"Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, con las palmas hacia adelante. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps"},{"id":"1669","name":"dumbbell one arm seated hammer curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1669-jK2hZ6n.gif","ins":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí). Apoya el codo en la parte interna del muslo, justo por encima de la rodilla"},{"id":"0126","name":"barbell wrist curl","grp":"biceps","eq":"barra","target":"forearms","gif":"0126-82LxxkW.gif","ins":"Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino. Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas. Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas"},{"id":"1647","name":"dumbbell alternate preacher curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1647-NlfIbzq.gif","ins":"Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba. Apoya la parte superior de los brazos en la almohadilla del banco scott, permitiendo que los brazos se extiendan completamente. Manteniendo los brazos superiores quietos, exhala y flexiona la mancuerna en tu mano derecha mientras contraes el bíceps"},{"id":"1633","name":"cable one arm preacher curl","grp":"biceps","eq":"polea","target":"biceps","gif":"1633-eHBlPsa.gif","ins":"Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott"},{"id":"0526","name":"kettlebell double alternating hang clean","grp":"biceps","eq":"kettlebell","target":"biceps","gif":"0526-a4F9Oyc.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen rectas frente a tu cuerpo"},{"id":"0317","name":"dumbbell incline curl v. 2","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0317-RaflbWD.gif","ins":"Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros"},{"id":"0313","name":"dumbbell hammer curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0313-slDvUAU.gif","ins":"Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial"},{"id":"0968","name":"band alternating biceps curl","grp":"biceps","eq":"banda","target":"biceps","gif":"0968-3omWx6P.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca de los costados y flexiona lentamente un brazo hacia el hombro, apretando el bíceps en la parte superior. Baja el brazo de vuelta a la posición inicial y repite con el otro brazo"},{"id":"2705","name":"dumbbell lying pronation on floor","grp":"biceps","eq":"mancuernas","target":"forearms","gif":"2705-7RWNjiB.gif","ins":"Túmbate boca abajo en el suelo con los brazos extendidos rectos frente a ti, sosteniendo una mancuerna en cada mano. Gira las palmas de modo que queden mirando hacia el suelo. Manteniendo los brazos rectos, levanta las mancuernas del suelo contrayendo los antebrazos"},{"id":"0452","name":"ez barbell reverse grip preacher curl","grp":"biceps","eq":"barra Z","target":"biceps","gif":"0452-vBNyir7.gif","ins":"Siéntate en un banco scott con el pecho apoyado en la almohadilla y los pies planos sobre el suelo. Sujeta la barra EZ con agarre supino, manos separadas a la altura de los hombros. Apoya los brazos superiores en la almohadilla, dejando que los antebrazos cuelguen hacia abajo"},{"id":"1654","name":"dumbbell biceps curl reverse","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"1654-nFc4FyV.gif","ins":"Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros"},{"id":"0403","name":"dumbbell seated revers grip concentration curl","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0403-lyKCLmK.gif","ins":"Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro"},{"id":"1643","name":"cable seated overhead curl","grp":"biceps","eq":"polea","target":"biceps","gif":"1643-DpWMFP5.gif","ins":"Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén la parte superior de los brazos inmóvil y los codos cerca de los costados"},{"id":"0390","name":"dumbbell seated biceps curl (on stability ball)","grp":"biceps","eq":"mancuernas","target":"biceps","gif":"0390-WgJnBH5.gif","ins":"Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps"},{"id":"3123","name":"resistance band seated biceps curl","grp":"biceps","eq":"banda","target":"biceps","gif":"3123-XFc3vpY.gif","ins":"Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén la banda elástica con un agarre supino, con las palmas hacia arriba y los brazos extendidos a los lados del cuerpo. Manteniendo la parte superior de los brazos inmóvil, exhala y flexiona la banda elástica hacia los hombros"},{"id":"0525","name":"kettlebell bottoms up clean from the hang position","grp":"biceps","eq":"kettlebell","target":"biceps","gif":"0525-4KJEpzb.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido"},{"id":"0437","name":"dumbbell upright row","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0437-ainizkb.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos. Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos"},{"id":"0553","name":"kettlebell two arm military press","grp":"hombros","eq":"kettlebell","target":"delts","gif":"0553-blBXysN.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante. Activa el core y presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial"},{"id":"0765","name":"smith seated shoulder press","grp":"hombros","eq":"multipower","target":"delts","gif":"0765-xUwnBMT.gif","ins":"Ajusta la altura del asiento de modo que las asas queden a la altura de los hombros. Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo. Sujeta las asas con un agarre prono y levántalas de los soportes, extendiendo los brazos por completo"},{"id":"0225","name":"cable standing cross-over high reverse fly","grp":"hombros","eq":"polea","target":"delts","gif":"0225-P5p0j8B.gif","ins":"Coloca un mango en D en cada lado de una máquina de cable a la altura de los hombros. Ponte de pie en el medio de la máquina de cable con los pies separados a la altura de los hombros. Agarra los mangos con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante"},{"id":"0438","name":"dumbbell w-press","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0438-vmwLyCg.gif","ins":"Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza"},{"id":"0869","name":"lever shoulder press v. 2","grp":"hombros","eq":"máquina","target":"delts","gif":"0869-vqsbmL0.gif","ins":"Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros"},{"id":"0772","name":"smith standing behind head military press","grp":"hombros","eq":"multipower","target":"delts","gif":"0772-ht8xDrP.gif","ins":"Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros"},{"id":"0386","name":"dumbbell rotation reverse fly","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0386-prbWx1D.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo"},{"id":"0997","name":"band shoulder press","grp":"hombros","eq":"banda","target":"delts","gif":"0997-peAeMR3.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies. Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados. Empuja la banda por encima de la cabeza, extendiendo completamente los brazos"},{"id":"0993","name":"band reverse fly","grp":"hombros","eq":"banda","target":"delts","gif":"0993-sTfvVsG.gif","ins":"Sujeta la banda a un objeto fijo a la altura del pecho. Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti. Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo"},{"id":"1456","name":"barbell standing close grip military press","grp":"hombros","eq":"barra","target":"delts","gif":"1456-wdRZISl.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, manos un poco más juntas que el ancho de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos cerca del cuerpo. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos"},{"id":"0774","name":"smith standing military press","grp":"hombros","eq":"multipower","target":"delts","gif":"0774-jjUPrze.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y bájala hasta la altura de los hombros, con las palmas hacia delante"},{"id":"0087","name":"barbell seated bradford rocky press","grp":"hombros","eq":"barra","target":"delts","gif":"0087-0dCyly0.gif","ins":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante"},{"id":"0178","name":"cable lateral raise","grp":"hombros","eq":"polea","target":"delts","gif":"0178-goJ6ezq.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono. Mantén los brazos rectos y el core activado. Levanta los brazos hacia los lados hasta que queden paralelos al suelo"},{"id":"0164","name":"cable front shoulder raise","grp":"hombros","eq":"polea","target":"delts","gif":"0164-mTT3KLn.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo"},{"id":"0332","name":"dumbbell iron cross","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0332-cALkHHX.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo. Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial"},{"id":"1012","name":"band twisting overhead press","grp":"hombros","eq":"banda","target":"delts","gif":"1012-u4bAmKp.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies. Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante. Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos"},{"id":"0392","name":"dumbbell seated front raise","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0392-Ys97II0.gif","ins":"Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas frente a ti, con las palmas hacia abajo, hasta que queden a la altura de los hombros"},{"id":"0067","name":"barbell one arm snatch","grp":"hombros","eq":"barra","target":"delts","gif":"0067-xHKN2s8.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado"},{"id":"0235","name":"cable standing shoulder external rotation","grp":"hombros","eq":"polea","target":"delts","gif":"0235-FWdVhcW.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta el mango del cable con el brazo extendido frente a ti, paralelo al suelo. Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás"},{"id":"0604","name":"lever shrug","grp":"hombros","eq":"máquina","target":"traps","gif":"0604-ZZKbeMw.gif","ins":"Ajusta la altura del asiento y colócate en la máquina de palanca con la espalda apoyada en la almohadilla. Sujeta las asas con un agarre prono y mantén los brazos rectos. Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible"},{"id":"0360","name":"dumbbell one arm shoulder press v. 2","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0360-1TkiAFK.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Activa el core y empuja la mancuerna directamente hacia arriba por encima de la cabeza, extendiendo completamente el brazo. Haz una pausa por un momento en la parte superior, luego baja lentamente la mancuerna de vuelta a la altura del hombro"},{"id":"0379","name":"dumbbell rear lateral raise (support head)","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0379-UzkLrem.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo"},{"id":"2397","name":"dumbbell scott press","grp":"hombros","eq":"mancuernas","target":"delts","gif":"2397-5vfAI0I.gif","ins":"Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos"},{"id":"0041","name":"barbell front raise","grp":"hombros","eq":"barra","target":"delts","gif":"0041-b2Uoz54.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado. Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial"},{"id":"0086","name":"barbell seated behind head military press","grp":"hombros","eq":"barra","target":"delts","gif":"0086-ngPpyRS.gif","ins":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza"},{"id":"0202","name":"cable rear delt row (stirrups)","grp":"hombros","eq":"polea","target":"delts","gif":"0202-yUdIGNs.gif","ins":"Sujeta un asa de estribo a una polea de cable baja y ponte de pie frente a la máquina. Sujeta el asa con la mano izquierda y retrocede un paso con el pie derecho, colocando el cuerpo en un ligero ángulo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado"},{"id":"0547","name":"kettlebell seesaw press","grp":"hombros","eq":"kettlebell","target":"delts","gif":"0547-UDm6cGl.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Presiona una pesa rusa por encima de la cabeza mientras mantienes la otra pesa rusa a la altura del hombro. Baja la pesa rusa presionada de vuelta a la altura del hombro mientras presionas simultáneamente la otra pesa rusa por encima de la cabeza"},{"id":"2271","name":"left hook. boxing","grp":"hombros","eq":"peso corporal","target":"delts","gif":"2271-hoXt6wv.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla. Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe"},{"id":"0355","name":"dumbbell one arm lateral raise","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0355-n5cWCsI.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo. Mantén la espalda recta y el core activado durante todo el ejercicio. Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo"},{"id":"0746","name":"smith back shrug","grp":"hombros","eq":"multipower","target":"traps","gif":"0746-MzNnwx9.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén los brazos rectos y deja que la barra cuelgue frente a los muslos"},{"id":"0286","name":"dumbbell alternate side press","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0286-izMnLqz.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros. Empuja una mancuerna por encima de la cabeza mientras mantienes la otra mancuerna a la altura del hombro. Baja la mancuerna empujada de vuelta a la altura del hombro mientras empujas la otra mancuerna por encima de la cabeza"},{"id":"0587","name":"lever military press","grp":"hombros","eq":"máquina","target":"delts","gif":"0587-CggQhII.gif","ins":"Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos"},{"id":"0075","name":"barbell rear delt raise","grp":"hombros","eq":"barra","target":"delts","gif":"0075-Ln9iTbU.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo"},{"id":"0406","name":"dumbbell shrug","grp":"hombros","eq":"mancuernas","target":"traps","gif":"0406-NJzBsGJ.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Mantén los brazos rectos y deja que las mancuernas cuelguen a tus costados. Eleva los hombros lo más alto posible, como si intentaras tocarte las orejas con ellos"},{"id":"3641","name":"weighted kneeling step with swing","grp":"hombros","eq":"lastre","target":"delts","gif":"3641-7uFJuXp.gif","ins":"Comienza en posición de rodillas con las rodillas separadas a la altura de las caderas y la espalda recta. Sostén un peso en cada mano, con los brazos extendidos rectos hacia abajo frente a ti. Activa el core y balancea los pesos hacia arriba y por encima de la cabeza, manteniendo los brazos rectos"},{"id":"3011","name":"incline scapula push up","grp":"hombros","eq":"peso corporal","target":"serratus anterior","gif":"3011-GdMa1ET.gif","ins":"Coloca un banco inclinado a un ángulo de 45 grados. Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros. Coloca los pies en el suelo, separados a la altura de las caderas"},{"id":"0759","name":"smith incline shoulder raises","grp":"hombros","eq":"multipower","target":"serratus anterior","gif":"0759-ayAHcEm.gif","ins":"Ajusta la máquina Smith a una posición inclinada. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros"},{"id":"3305","name":"barbell thruster","grp":"hombros","eq":"barra","target":"delts","gif":"3305-f7Y9eDZ.gif","ins":"Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono. Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza"},{"id":"2318","name":"lever shoulder press v. 3","grp":"hombros","eq":"máquina","target":"delts","gif":"2318-dNFYIU1.gif","ins":"Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros"},{"id":"0844","name":"weighted round arm","grp":"hombros","eq":"lastre","target":"delts","gif":"0844-VLYXo8S.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Eleva los brazos hacia los lados, manteniendo una ligera flexión en los codos"},{"id":"0383","name":"dumbbell reverse fly","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0383-EAs3xL9.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí"},{"id":"0299","name":"dumbbell cuban press","grp":"hombros","eq":"mancuernas","target":"delts","gif":"0299-QfAKy1G.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo. Manteniendo el core activado y los codos ligeramente flexionados, empuja las mancuernas hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos. Gira las muñecas de modo que las palmas queden mirando hacia adelante"},{"id":"1457","name":"barbell standing wide military press","grp":"hombros","eq":"barra","target":"delts","gif":"1457-Kyd9Rz5.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos"},{"id":"0162","name":"cable front raise","grp":"hombros","eq":"polea","target":"delts","gif":"0162-u2X71Np.gif","ins":"Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo"}];
